const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountCustomerAssistant(root,{api,getBusiness,applyDescription}){
 root._localAiAbort?.abort();const controller=new AbortController();root._localAiAbort=controller;
 const dialog=document.createElement('dialog');dialog.id='local-ai-dialog';dialog.className='customer-dialog assistant-dialog';dialog.setAttribute('aria-labelledby','assistant-title');root.append(dialog);
 let generation=0;
 async function open(mode,leadId=''){
  generation++;dialog.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">ASSISTENTE HELPU</span><h2 id="assistant-title">${mode==='reply'?'Uma boa conversa começa aqui.':'Conte melhor o que você faz.'}</h2></div><button class="chip" type="button" data-ai-close aria-label="Fechar assistente">×</button></div><p class="muted">${mode==='reply'?'Prepare uma resposta usando o pedido recebido e as informações do seu negócio.':'Transforme as informações do seu negócio em uma apresentação clara.'}</p><form id="local-ai-form"><label>O que a IA precisa considerar?<textarea name="guidance" maxlength="2000" rows="3" placeholder="${mode==='reply'?'Ex.: temos disponibilidade às 19h; confirmar quantas pessoas.':'Ex.: fazemos passeios em pequenos grupos; atendemos famílias.'}"></textarea></label><p class="helper">Revise os fatos antes de usar. A sugestão não é publicada nem enviada automaticamente.</p><p role="alert"></p><button type="submit" class="primary">Gerar sugestão</button></form><div id="local-ai-result" aria-live="polite"></div>`;
  dialog.showModal();const form=dialog.querySelector('form');
  form.addEventListener('submit',async e=>{e.preventDefault();const ticket=++generation,button=form.querySelector('button'),status=form.querySelector('[role=alert]');button.disabled=true;status.textContent='Preparando sua sugestão…';dialog.querySelector('#local-ai-result').innerHTML='';try{const d=await api('assistant',{mode,leadId,guidance:form.elements.guidance.value,description:mode==='profile'?(document.querySelector('#profile [name=description]')?.value||getBusiness().description):''});if(ticket!==generation||!dialog.open)return;status.textContent='';const result=dialog.querySelector('#local-ai-result');result.innerHTML=`<div class="ai-draft"><span class="eyebrow">SUGESTÃO PARA REVISÃO</span><label>Texto editável<textarea id="ai-draft-text" rows="7" maxlength="4000">${esc(d.text)}</textarea></label>${d.questions?.length?'<h3>Antes de concluir</h3><ul>'+d.questions.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}${d.recommendations?.length?'<h3>Para melhorar</h3><ul>'+d.recommendations.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}<div class="ai-actions"><button type="button" class="primary" data-use-ai>${mode==='profile'?'Usar na descrição':'Copiar resposta'}</button></div><p role="status"></p></div>`;result.querySelector('[data-use-ai]').addEventListener('click',async()=>{const text=result.querySelector('textarea').value;if(mode==='profile'){if(text.length>3000){result.querySelector('[role=status]').textContent='Reduza a descrição para até 3.000 caracteres.';return;}dialog.close();applyDescription(text);}else{try{await navigator.clipboard.writeText(text);result.querySelector('[role=status]').textContent='Resposta copiada. Revise e envie pelo seu WhatsApp.';}catch{result.querySelector('textarea').select();result.querySelector('[role=status]').textContent='Selecione e copie o texto acima.';}}});}catch(err){if(ticket===generation)status.textContent=err.message;}finally{if(ticket===generation){button.disabled=false;button.textContent='Gerar outra sugestão';}}});
 }
 dialog.addEventListener('click',e=>{if(e.target.closest('[data-ai-close]'))dialog.close();});dialog.addEventListener('close',()=>generation++);
 root.addEventListener('click',e=>{const button=e.target.closest('[data-ai-mode]');if(button)open(button.dataset.aiMode,button.dataset.aiLead||'');},{signal:controller.signal});
}
